function normalizeState(raw){const base=emptyState(),source=raw&&typeof raw==="object"&&!Array.isArray(raw)?raw:{};const next={...base,...source};for(const key of ["duties","reminders","events","workouts","shopping","expenses","incomes","debts","assets","sleepLogs","healthDaily","healthWorkouts","dailyCheckins","hydrationLogs","habitLogs","habits","logbook","recommendations","mealPlan","pantry","customRecipes","recipeSearchResults","favoriteRecipes","trainingPlan","trainingGoals","aviationTraining","aiLog","rosterHotels","rosterTraining","airportNotes","crewBids","crewBidHistory","fitnessWeightLogs"])if(!Array.isArray(next[key]))next[key]=[];next.fitnessJourney=normalizeFitnessJourneyProfile(next.fitnessJourney||FITNESS_JOURNEY_DEFAULTS);if(!next.nutritionProfile||typeof next.nutritionProfile!=="object")next.nutritionProfile={weightKg:next.fitnessWeightLogs?.slice(-1)[0]?.weightKg||next.fitnessJourney.startWeightKg||114,goalWeightKg:80,heightCm:next.fitnessJourney.heightCm||170,age:38,sex:"male",goal:"lose",activityFactor:1.4,deficitKcal:350,allergens:"",avoidIngredients:""};if(!Array.isArray(next.receiptDraftItems))next.receiptDraftItems=[];if(!next.budgets||typeof next.budgets!=="object"||Array.isArray(next.budgets))next.budgets={};next.crewBiddingProfile=normalizeCrewBiddingProfile(next.crewBiddingProfile);return next}
