 const goalOptions=[["general","General fitness"],["strength","Strength & muscle"],["fat-loss","Fat loss & conditioning"],["endurance","Cardiovascular endurance"],["mobility","Mobility & resilience"]];
 const goal=profile.goal||"general",setting=profile.setting||"gym",minutes=Number(profile.availableMinutes)||40,days=Number(profile.daysPerWeek)||3;
