 const exerciseCards=EXERCISES.map(x=>{const next=suggestNextLoad(workouts,x.id),search=[x.name,x.pattern,...x.muscles,...x.equipment].join(" ").toLowerCase();return `<article class="exercise-library-card" data-exercise-search="${esc(search)}"><div class="exercise-library-art"><div class="guided-figure" data-exercise-sequence="${esc(x.id)}">${exerciseDemoSvg(x.id)}</div></div><div class="exercise-library-copy"><b>${esc(x.name)}</b><small>${esc(x.pattern)} · ${esc(x.muscles.join(", "))}</small><small class="muted">${esc(x.equipment.join(", "))} · ${esc(x.level)}</small><p>${esc(x.cues[0])}</p><small class="muted">${esc(next.message)}</small><button class="btn ghost" data-use-library-exercise="${x.id}">Añadir a sesión</button></div></article>`}).join("");
 const dutyCount=(state.duties||[]).filter(x=>x.date>=today()&&x.date<=shiftDate(today(),13)).length;
 const recentSets=workouts.flatMap(w=>(w.exercises||[]).flatMap(ex=>(ex.setLog||[]).map(s=>({...s,exerciseId:ex.exerciseId,date:w.date}))));const totalVolume=recentSets.reduce((n,s)=>n+(Number(s.reps)||0)*(Number(s.weight)||0),0);const avgRpe=recentSets.length?recentSets.reduce((n,s)=>n+(Number(s.rpe)||0),0)/recentSets.length:null;const history=recent.length?recent.map(x=>`<div class="row"><span><b>${dateText(x.date)} · ${esc(x.activity||x.type||"Workout")}</b><small>${Number(x.minutes)||0} min${x.distanceKm!=null?" · "+Number(x.distanceKm).toFixed(2)+" km":""}${x.cardioRpe?" · RPE "+x.cardioRpe:""}${x.averageHeartRate?" · FC "+x.averageHeartRate+" bpm":""} · ${esc(x.setting||"Not specified")} · ${esc(x.notes||"")}</small></span><span class="muted">${(x.exercises||[]).reduce((n,e)=>n+(e.setLog||[]).length,0)} sets</span></div>`).join(""):'<div class="empty">Registra tu primera sesión para que el entrenador pueda aprender de tu evolución.</div>';
 const activeSessionPanel=activeWorkout?'<section class="panel active-workout-panel"><div class="active-workout-top"><div><div class="kicker">NOW TRAINING</div><h2>'+esc(activeWorkout.title||"Training session")+'</h2><p>'+dateText(activeWorkout.date||today())+' · '+esc(activeWorkout.setting||"gym")+' · '+Number(activeWorkout.minutes||0)+' min target</p></div><button class="btn ghost" id="cancelActiveWorkout">Exit session</button></div><div class="active-workout-timer"><div class="active-timer-ring"><span id="activeWorkoutClock">'+formatClock(workoutElapsed())+'</span><small id="activeWorkoutClockStatus">'+(state.workoutTimer?.running?"IN PROGRESS":workoutElapsed()?"PAUSED":"READY")+'</small></div><div class="active-timer-controls"><button class="btn primary" id="startWorkoutClock">Start / resume</button><button class="btn ghost" id="pauseWorkoutClock">Pause</button><button class="btn ghost" id="startRestClock">Rest 90 sec</button><span class="rest-clock-row">REST <b id="activeRestClock">'+formatClock(Math.max(0,(Number(state.restTimer?.endsAt)||0)-Date.now()))+'</b></span></div></div>'+guidedExercisePanel()+'<div class="active-workout-footer"><span>'+draftExercises.reduce((n,x)=>n+(x.setLog||[]).length,0)+' / '+draftExercises.reduce((n,x)=>n+Number(x.sets||0),0)+' sets completed</span><button class="btn primary" id="finishActiveWorkout">Finish & save workout</button></div></section>':'';

