function recipeTimeLabel(value){return Number(value)>0?Number(value)+" min":"Tiempo no verificado"}
function nutrition(){
 const meals=state.mealPlan||[],pantry=state.pantry||[],open=state.shopping.filter(x=>!x.done),recipes=allRecipes(),candidates=state.recipeSearchResults||[],selected=candidates.find(x=>x.id===state.selectedRecipeCandidate),np=state.nutritionProfile||{weightKg:114,goalWeightKg:80,heightCm:170,age:38,sex:"male",goal:"lose",activityFactor:1.4,deficitKcal:350},target=nutritionTargets(np),favoriteIds=state.favoriteRecipes||[];
 const diary=state.foodDiary||[],diaryToday=nutritionDiarySummary(diary,recipes,today()),safeRecipes=filterRecipesByProfile(recipes,np);
 const diaryRows=diary.filter(x=>x.date===today()).map(x=>{const r=recipeById(x.recipeId),n=r?recipeNutrition(r):null;return '<div class="row"><span><b>'+esc(r?.name||"Food item")+'</b><small>'+esc(x.mealType)+' · '+x.servings+' ración(es)</small></span><b>'+(n?.verified?Math.round(n.perServing.kcal*x.servings)+' kcal':'Macros n/d')+'</b><button class="btn ghost" data-diary-remove="'+diary.indexOf(x)+'">×</button></div>'}).join("");
 const byDay=new Map();for(const m of meals){if(!byDay.has(m.date))byDay.set(m.date,[]);byDay.get(m.date).push(m)}const calorieProgress=target.status==="estimate"?Math.min(100,Math.round(diaryToday.kcal/Math.max(1,target.target)*100)):0,proteinProgress=target.status==="estimate"?Math.min(100,Math.round(diaryToday.proteinG/Math.max(1,target.proteinG)*100)):0;
 const image=r=>{if(r.image&&/^https?:\/\//i.test(String(r.image)))return '<img src="'+esc(r.image)+'" alt="'+esc(r.name)+'" loading="lazy" referrerpolicy="no-referrer" onerror="this.outerHTML=\'<div class=&quot;recipe-image-missing&quot;>Fotografía no disponible</div>\'">';return '<div class="recipe-image-missing">Fotografía no disponible</div>';};
 const recipeCards=recipes.map(r=>{const n=recipeNutrition(r),fav=favoriteIds.includes(r.id);return '<article class="recipe-visual-card">'+image(r)+'<div class="recipe-visual-copy"><b>'+esc(r.name)+'</b><small>'+esc(r.category)+' · '+recipeTimeLabel(r.minutes)+' · '+r.servings+' raciones</small><strong>'+(n.verified?n.perServing.kcal+' kcal/ración':'Macros incompletos · '+n.coverage+'%')+'</strong>'+(n.verified?'<small>P '+n.perServing.protein+'g · C '+n.perServing.carbs+'g · G '+n.perServing.fat+'g · estimación</small>':'<small>Faltan pesos o datos de '+esc(n.unknownIngredients.join(", "))+'</small>')+'<div class="recipe-card-actions"><button class="btn ghost" data-recipe="'+esc(r.id)+'">Ver receta</button><button class="btn ghost" data-favorite-recipe="'+esc(r.id)+'">'+(fav?'★ Favorita':'☆ Guardar')+'</button><button class="btn ghost" data-adapt-recipe="'+esc(r.id)+'" data-mode="light">Ligera</button><button class="btn ghost" data-adapt-recipe="'+esc(r.id)+'" data-mode="high-protein">+ Proteína</button><button class="btn ghost" data-adapt-recipe="'+esc(r.id)+'" data-mode="low-carb">Low carb</button></div></div></article>'}).join("");
 const planRows=byDay.size?[...byDay].sort((a,b)=>a[0].localeCompare(b[0])).map(([date,items])=>'<div class="meal-day"><div class="meal-day-head"><b>'+dateText(date)+'</b><small>'+esc(items[0].context||"Menú familiar")+'</small></div><div class="meal-visual-grid">'+items.map(m=>{const r=recipeById(m.recipeId)||RECIPES[0],n=recipeNutrition(r);return '<article class="meal-visual-card">'+image(r)+'<div class="meal-visual-copy"><small>'+esc(m.slot||"Comida")+'</small><b>'+esc(r.name)+'</b><span>'+m.servings+' raciones · '+recipeTimeLabel(m.minutes)+' · '+(n.verified?n.perServing.kcal+' kcal/ración':'macros no verificados')+'</span><select data-meal-recipe data-meal-date="'+esc(m.date)+'" data-meal-slot="'+esc(m.slot)+'" aria-label="Cambiar plato"><option value="">Cambiar plato…</option>'+recipes.filter(x=>x.category===r.category).map(x=>'<option value="'+esc(x.id)+'" '+(x.id===r.id?"selected":"")+'>'+esc(x.name)+'</option>').join("")+'</select><button class="btn ghost" data-recipe="'+esc(r.id)+'">Ver preparación</button></div></article>'}).join("")+'</div></div>').join("")+'<div class="form"><button class="btn primary" id="makeMealShopping">Crear lista de compra desde el menú</button><button class="btn ghost" id="clearMealPlan">Vaciar borrador</button></div>':'<div class="empty">Genera un menú mediterráneo de siete días o busca una receta para añadirla.</div>';
 const candidateCards=candidates.map(r=>'<article class="recipe-visual-card">'+image(r)+'<div class="recipe-visual-copy"><b>'+esc(r.name)+'</b><small>'+esc(r.origin==="web"?"Receta publicada":r.origin==="social-import"?"Importada de red social":"Receta propia / adaptada")+' · '+recipeTimeLabel(r.minutes)+' · '+r.servings+' raciones</small><button class="btn '+(r.id===state.selectedRecipeCandidate?"primary":"ghost")+'" data-recipe-candidate="'+esc(r.id)+'">'+(r.id===state.selectedRecipeCandidate?"Seleccionada":"Revisar receta")+'</button><button class="btn ghost" data-favorite-recipe="'+esc(r.id)+'">☆ Guardar favorita</button></div></article>').join("");
 const selectedNutrition=selected?recipeNutrition(selected):null;
 const selectedPanel=selected?'<section class="panel recipe-review"><div class="panel-head"><h2>REVISIÓN ANTES DE AÑADIR</h2><span class="pill">'+(selected.origin==="web"?"Fuente pública":selected.origin==="social-import"?"Red social":"Receta propia / adaptada")+'</span></div><div class="recipe-review-grid">'+image(selected)+'<div><h3>'+esc(selected.name)+'</h3><p class="muted">'+recipeTimeLabel(selected.minutes)+' · '+selected.servings+' raciones · '+(selectedNutrition.complete?selectedNutrition.perServing.kcal+' kcal/ración aprox.':'macros incompletos: '+selectedNutrition.coverage+'%')+'</p>'+(selected.sourceUrl?'<p><a href="'+esc(selected.sourceUrl)+'" target="_blank" rel="noopener noreferrer">Abrir receta original ↗</a></p>':'<p class="muted">Receta propia de RUMBO.</p>')+'</div></div><h3>Ingredientes · peso y nutrición</h3><div class="table-scroll"><table class="nutrition-ingredient-table"><thead><tr><th>Ingrediente</th><th>Cantidad</th><th>Base</th><th>kcal</th><th>Proteína</th></tr></thead><tbody>'+selectedNutrition.ingredients.map(x=>'<tr><td>'+esc(x.name)+'</td><td>'+esc(x.quantity)+'</td><td>'+esc(x.basis==="cooked"?"Cocinado":"Crudo")+'</td><td>'+(x.covered?Math.round(x.kcal):"—")+'</td><td>'+(x.covered?Math.round(x.protein*10)/10+" g":"—")+'</td></tr>').join("")+'</tbody></table></div>'+(selectedNutrition.complete?'<p class="muted">Total receta: '+selectedNutrition.total.kcal+' kcal · '+selectedNutrition.total.protein+' g proteína. Por ración: '+selectedNutrition.perServing.kcal+' kcal · '+selectedNutrition.perServing.protein+' g proteína. Valores orientativos.</p>':'<p class="callout">Para completar los macros, añade pesos en gramos y marca si el peso corresponde al alimento crudo o cocinado. No estimamos cantidades sin base.</p>')+'<h3>Preparación</h3><ol>'+selected.steps.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ol><div class="fitness-evidence-note"><b>LOTE FAMILIAR · PESO FINAL COCINADO</b><div class="form"><label>Peso total del lote cocinado · g<input id="recipeCookedYield" type="number" min="1" step="1" value="'+(selected.batchCookedWeightGrams||"")+'"></label><label>Peso cocinado por ración · g<input id="recipePortionCooked" type="number" min="1" step="1" value="'+(selected.portionCookedWeightGrams||"")+'"></label><button class="btn ghost" id="calculateRecipeBatch">Calcular raciones y macros</button></div><div id="recipeBatchResult" class="muted">Introduce el peso final cocinado y el peso de cada ración para repartir el lote sin asumir mermas.</div></div><div class="form"><button class="btn primary" id="confirmRecipeAdd">Confirmar y añadir al menú + compra</button><button class="btn ghost" id="cancelRecipeReview">Cancelar</button></div><small class="muted">No se guarda ni se incorpora nada al menú hasta confirmar.</small></section>':'';
 const searchPanel='<section class="panel recipe-search-panel"><div class="panel-head"><h2>BUSCADOR DE RECETAS</h2><span class="pill">CATÁLOGO PÚBLICO</span></div><p class="muted">Busca por plato o ingrediente y, si quieres, limita por cocina. Consultamos recetas publicadas, recuperamos ingredientes y pasos y mostramos su fuente antes de añadirlas.</p><div class="recipe-search-form"><input id="recipeSearchQuery" maxlength="180" placeholder="Ej. carbonara, paella, pollo al curry, salmón…" value="'+esc(state.recipeSearchQuery||"")+'"><select id="recipeSearchCuisine"><option value="">Todas las cocinas</option><option value="Spanish" '+(state.recipeCuisine==="Spanish"?"selected":"")+'>Española</option><option value="Italian" '+(state.recipeCuisine==="Italian"?"selected":"")+'>Italiana</option><option value="German" '+(state.recipeCuisine==="German"?"selected":"")+'>Alemana</option><option value="American" '+(state.recipeCuisine==="American"?"selected":"")+'>Americana</option><option value="Mediterranean" '+(state.recipeCuisine==="Mediterranean"?"selected":"")+'>Mediterránea</option><option value="Asian" '+(state.recipeCuisine==="Asian"?"selected":"")+'>Asiática</option></select><select id="recipeSearchCategory"><option value="Breakfast" '+(state.recipeTargetCategory==="Breakfast"?"selected":"")+'>Desayuno</option><option value="Lunch" '+(!state.recipeTargetCategory||state.recipeTargetCategory==="Lunch"?"selected":"")+'>Comida</option><option value="Dinner" '+(state.recipeTargetCategory==="Dinner"?"selected":"")+'>Cena</option></select><input id="recipeSearchServings" type="number" min="1" max="12" value="'+(state.recipeTargetServings||4)+'" aria-label="Raciones"><input id="recipeSearchDate" type="date" value="'+esc(state.recipeSearchDate||state.mealWeekStart||today())+'"><button class="btn primary" id="searchRecipes">Buscar en catálogo</button><button class="btn ghost" id="searchWebRecipes" type="button">Buscar en toda la web ↗</button></div><small class="muted">El catálogo recupera recetas estructuradas. La búsqueda web abre resultados externos de Google; revisa la fuente original antes de importar.</small>'+(state.recipeSearchNotice?'<p class="muted recipe-search-notice">'+esc(state.recipeSearchNotice)+'</p>':'')+(candidates.length?'<div class="recipe-candidate-grid">'+candidateCards+'</div>':'')+'</section>';
 const customRecipePanel='<section class="panel recipe-search-panel"><div class="panel-head"><h2>MI RECETARIO · IMPORTAR O CREAR</h2><span class="pill">RECETA PROPIA</span></div><p class="muted">Pega una receta completa. Para TikTok, Instagram o YouTube, añade también el caption o la transcripción: las plataformas no permiten una extracción fiable de todos los vídeos y RUMBO no descarga contenido privado.</p><div class="social-recipe-import"><label>Enlace original · TikTok, Instagram, YouTube o web<input id="socialRecipeUrl" type="url" placeholder="https://…"></label><label>Caption, descripción o transcripción<textarea id="socialRecipeText" rows="4" placeholder="Pega ingredientes, cantidades y pasos que aparecen en el vídeo…"></textarea></label><button class="btn primary" id="importSocialRecipe">Importar desde red social / enlace</button><small class="muted">Se conserva el enlace original. El análisis del texto funciona en el navegador y no requiere suscripciones.</small></div><div class="divider"></div><label class="recipe-paste-label">Pegar receta completa<textarea id="recipePasteText" rows="7" placeholder="Carbonara tradicional&#10;4 raciones · 25 minutos&#10;&#10;Ingredientes&#10;- 400 g de espaguetis&#10;- 150 g de guanciale&#10;- 4 huevos&#10;- 80 g de pecorino&#10;&#10;Preparación&#10;1. Cuece la pasta en agua abundante.&#10;2. Dora el guanciale y mezcla los huevos con el queso.&#10;3. Combina fuera del fuego y sirve."></textarea></label><div class="form"><button class="btn primary" id="detectPastedRecipe">Detectar ingredientes y elaboración</button><span class="muted" id="recipeParseStatus">El detector funciona en el navegador; no envía tu texto a terceros.</span></div><div class="divider"></div><p class="muted">Revisa o corrige el resultado detectado antes de guardarlo. También puedes crear una receta manualmente.</p><div class="form"><input id="customRecipeName" maxlength="100" placeholder="Nombre de la receta"><select id="customRecipeCategory"><option value="Breakfast">Desayuno</option><option value="Lunch">Comida</option><option value="Dinner">Cena</option></select><input id="customRecipeServings" type="number" min="1" max="20" value="4" aria-label="Raciones"><input id="customRecipeMinutes" type="number" min="1" max="300" value="30" aria-label="Minutos"></div><label>Ingredientes · uno por línea: ingrediente | cantidad<textarea id="customRecipeIngredients" rows="5" placeholder="Pechuga de pollo | 150 g crudo&#10;Arroz blanco | 120 g cocido&#10;Aceite de oliva | 5 g"></textarea></label><label>Elaboración · un paso por línea<textarea id="customRecipeSteps" rows="5" placeholder="Lavar y cortar los ingredientes.&#10;Cocinar a fuego medio hasta que estén hechos."></textarea></label><div class="form"><input id="customRecipeCookedYield" type="number" min="0" step="1" placeholder="Peso final del lote cocinado · g"><input id="customRecipePortionCooked" type="number" min="0" step="1" placeholder="Peso cocinado por ración · g"></div><div class="form"><input id="customRecipeKcal" type="number" min="0" max="5000" placeholder="kcal por ración (opcional)"><input id="customRecipeProtein" type="number" min="0" max="300" step=".1" placeholder="Proteína g/ración"><input id="customRecipeCarbs" type="number" min="0" max="500" step=".1" placeholder="Carbohidratos g/ración"><input id="customRecipeFat" type="number" min="0" max="300" step=".1" placeholder="Grasas g/ración"></div><button class="btn primary" id="saveCustomRecipe">Guardar en mi recetario</button></section>';

return head("RUMBO KITCHEN · NUTRICIÓN","Nutrición familiar inteligente","Recetario mediterráneo, importación de recetas, versiones ligeras y altas en proteína, planificación semanal y compra sincronizada con Fitness.",'<div class="form"><input id="mealWeekStart" type="date" value="'+(state.mealWeekStart||today())+'"><button class="btn primary" id="generateMeals">Generar menú de 7 días</button></div>')+
 '<div class="grid four">'+metric("MEALS PLANNED",meals.length)+metric("SHOPPING ITEMS",open.length)+metric("PANTRY ITEMS",pantry.length)+metric("RECIPE LIBRARY",recipes.length)+'</div>'+panel("OBJETIVOS DIARIOS · CONECTADOS A FITNESS",'<div class="grid two"><div><b>'+diaryToday.kcal+' / '+(target.target||"—")+' kcal</b><div class="fitness-progress-track"><span style="width:'+calorieProgress+'%"></span></div><small class="muted">Calorías registradas · objetivo orientativo</small></div><div><b>'+diaryToday.proteinG+' / '+(target.proteinG||"—")+' g proteína</b><div class="fitness-progress-track"><span style="width:'+proteinProgress+'%"></span></div><small class="muted">Proteína registrada · objetivo calculado sobre peso objetivo</small></div></div>')+customRecipePanel+searchPanel+selectedPanel+
 '<div class="grid two" style="margin-top:14px">'+panel("MENÚ SEMANAL · 7 DÍAS",planRows)+
 panel("ADD TO SHOPPING LIST",'<div class="form"><input id="shopItem" placeholder="Ingrediente / producto"><input id="shopQty" placeholder="Cantidad"><button class="btn primary" id="addShop">Añadir</button></div>')+
 panel("SHOPPING LIST",open.length?state.shopping.map((x,i)=>'<label class="item"><input type="checkbox" data-shop="'+i+'" '+(x.done?"checked":"")+'><span class="grow" style="'+(x.done?"text-decoration:line-through;opacity:.5":"")+'">'+esc(x.name)+' <small>'+esc(x.qty)+'</small></span><span class="pill">'+esc(x.source||"manual")+'</span></label>').join(""):'<div class="empty">La lista de la compra está vacía.</div>')+
 panel("PANTRY / INVENTORY",'<div class="form"><input id="pantryName" placeholder="Ingrediente en despensa"><input id="pantryQty" placeholder="Cantidad"><input id="pantryExpiry" type="date" aria-label="Fecha de caducidad"><button class="btn primary" id="addPantry">Añadir existencias</button></div>'+pantry.map((x,i)=>'<div class="row"><span><b>'+esc(x.name)+'</b><small>'+esc(x.qty)+(x.expiryDate?' · Caduca: '+dateText(x.expiryDate):' · Caducidad no registrada')+' · '+(pantryExpiryStatus(x)==="expired"?'CADUCADO':pantryExpiryStatus(x)==="soon"?'CADUCA PRONTO':pantryExpiryStatus(x)==="fresh"?'En fecha':'Sin fecha')+'</small></span><button class="btn ghost" data-pantry-remove="'+i+'">×</button></div>').join("")||'<div class="empty">Añade lo que ya tienes. RUMBO lo descontará de futuras compras.</div>')+
 panel("FOOD DIARY · TODAY",'<p class="muted">Log meals by recipe and serving size. Nutrients are estimates based on listed ingredients.</p><div class="grid four">'+metric("KCAL",diaryToday.kcal)+metric("PROTEIN",diaryToday.proteinG+" g")+metric("CARBS",diaryToday.carbsG+" g")+metric("FAT",diaryToday.fatG+" g")+'</div><small class="muted">Los registros sin valores nutricionales verificados no se incluyen en los totales.</small><div class="form"><input id="diaryDate" type="date" value="'+today()+'"><select id="diaryMealType"><option>Breakfast</option><option>Lunch</option><option>Dinner</option><option>Snack</option></select><select id="diaryRecipe" class="grow"><option value="">Choose recipe / food</option>'+safeRecipes.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.name)+'</option>').join("")+'</select><input id="diaryServings" type="number" min=".25" max="20" step=".25" value="1"><button class="btn primary" id="addFoodDiary">Log food</button></div>'+diaryRows)+
 panel("PERSONAL NUTRITION PROFILE",'<p class="muted">Estimaciones, no prescripción médica o dietética.</p><div class="form"><input id="nutriWeight" type="number" min="25" max="300" step=".1" placeholder="Peso kg" value="'+(np.weightKg||"")+'"><input id="nutriGoalWeight" type="number" min="30" max="250" step=".1" placeholder="Peso objetivo kg" value="'+(np.goalWeightKg||80)+'"><input id="nutriHeight" type="number" min="100" max="230" placeholder="Altura cm" value="'+(np.heightCm||"")+'"><input id="nutriAge" type="number" min="18" max="100" placeholder="Edad" value="'+(np.age||"")+'"><input id="nutriDeficit" type="number" min="250" max="500" step="50" placeholder="Déficit kcal" value="'+(np.deficitKcal||350)+'"></div><div class="form"><select id="nutriSex"><option value="unspecified">Sexo (opcional)</option><option value="male" '+(np.sex==="male"?"selected":"")+'>Hombre</option><option value="female" '+(np.sex==="female"?"selected":"")+'>Mujer</option></select><select id="nutriGoal"><option value="maintain">Mantener peso</option><option value="lose" '+(np.goal==="lose"?"selected":"")+'>Perder peso</option><option value="gain" '+(np.goal==="gain"?"selected":"")+'>Ganar peso / músculo</option></select><select id="nutriActivity"><option value="1.2">Actividad baja</option><option value="1.4" '+(Number(np.activityFactor)===1.4?"selected":"")+'>Actividad ligera</option><option value="1.6" '+(Number(np.activityFactor)===1.6?"selected":"")+'>Actividad moderada</option><option value="1.75" '+(Number(np.activityFactor)===1.75?"selected":"")+'>Actividad alta</option></select><input id="nutriAllergens" placeholder="Allergens / intolerances (comma separated)" value="'+esc(np.allergens||"")+'"><input id="nutriAvoid" placeholder="Ingredients to avoid (comma separated)" value="'+esc(np.avoidIngredients||"")+'"><button class="btn primary" id="saveNutritionProfile">Save profile & calculate</button></div><div class="callout"><b>OBJETIVO DIARIO</b><p>'+(target.status==="estimate"?target.target+" kcal/día · mantenimiento "+target.maintenance+" kcal · proteína orientativa "+target.proteinG+" g/día · déficit "+target.deficitKcal+" kcal":target.note)+'</p></div>')+
 panel("RECETARIO · MEDITERRÁNEO · FAMILIAR · LOW CARB",'<div class="recipe-visual-grid">'+recipeCards+'</div>')+
 panel("BATCH COOKING · CONSERVACIÓN SEGURA",'<div class="callout"><b>PREPARACIÓN ANTICIPADA</b><p>Refrigera pronto en recipientes poco profundos; conserva sobras cocinadas 3–4 días a 4 °C o menos y congela lo que no vayas a consumir en ese plazo. No dejes alimentos perecederos fuera más de 2 horas, o 1 hora si el ambiente supera 32 °C. En días de vuelo, utiliza bolsa térmica y acumuladores fríos.</p><p><a href="https://ask.fsis.usda.gov/article/How-do-i-handle-leftovers-safely" target="_blank" rel="noopener">Guía USDA de conservación de sobras ↗</a></p></div>')+'</div>';
}
