function ai(){
 const c=buildAssistantContext(state),logs=state.aiLog||[];
 const next=state.duties.filter(x=>x.date>=today()).sort((a,b)=>a.date.localeCompare(b.date))[0];
 const expiringRecords=(state.aviationTraining||[]).filter(x=>x.expiry&&x.expiry<=shiftDate(today(),90)).sort((a,b)=>a.expiry.localeCompare(b.expiry)),expiring=expiringRecords.length;
 const monthKey=today().slice(0,7),month=monthRosterSummary(state.duties,monthKey),monthSectors=state.logbook.filter(x=>String(x.date||"").startsWith(monthKey)),monthHours=monthSectors.reduce((n,x)=>n+Number(x.hours||0),0);
 const nextWeek=state.duties.filter(x=>x.date>=today()&&x.date<=shiftDate(today(),7)).sort((a,b)=>a.date.localeCompare(b.date));
 const upcomingFamily=state.events.filter(x=>x.date>=today()&&x.date<=shiftDate(today(),14)).sort((a,b)=>a.date.localeCompare(b.date));
 const insights=[];
 if(expiring)insights.push({level:expiringRecords.some(x=>x.expiry<today())?"urgent":"attention",title:"Training validity review",detail:expiringRecords.length+" record(s) expired or due within 90 days. First: "+expiringRecords[0].title+" · "+dateText(expiringRecords[0].expiry),target:"training"});
 if(!nextWeek.length)insights.push({level:"info",title:"No upcoming roster entries",detail:"No imported duties found in the next 7 days. This does not confirm OFF days.",target:"roster"});
 if(nextWeek.length)insights.push({level:"info",title:"Next roster activity",detail:dateText(nextWeek[0].date)+" · "+(nextWeek[0].code||rosterType(nextWeek[0]))+" · "+(nextWeek[0].route||"route not specified"),target:"roster"});
 if(upcomingFamily.length)insights.push({level:"info",title:"Family calendar ahead",detail:upcomingFamily.length+" event(s) in the next 14 days. Next: "+upcomingFamily[0].title+" · "+dateText(upcomingFamily[0].date),target:"family"});
 if(month.FLIGHT!==new Set(monthSectors.map(x=>x.date)).size)insights.push({level:"attention",title:"Roster / logbook cross-check",detail:"Roster flight days ("+month.FLIGHT+") and logbook flight dates ("+new Set(monthSectors.map(x=>x.date)).size+") differ for "+monthKey+". Review imports before drawing conclusions.",target:"aviation"});
 if(!insights.length)insights.push({level:"success",title:"No priority alerts",detail:"No urgent local-data checks were identified. Keep records up to date.",target:"home"});
 return head("RUMBO INTELLIGENCE","RUMBO AI","Asistente local gratuito. Analiza tus datos guardados en este dispositivo sin API, sin coste y sin enviarlos a terceros.")+
 `<div class="grid four">${metric("ROSTER ENTRIES",c.duties)}${metric("LOGBOOK SECTORS",state.logbook.length)}${metric("TRAINING RECORDS",(state.aviationTraining||[]).length)}${metric("VALIDITY ALERTS",expiring)}</div>
 <section class="panel" style="margin-top:14px"><div class="panel-head"><div><div class="kicker">RULE-BASED PERSONAL REVIEW</div><h2>PRIORITY INSIGHTS</h2></div><span class="pill">LOCAL DATA</span></div>${insights.map(x=>`<div class="row"><span><b>${esc(x.title)}</b><small>${esc(x.detail)}</small></span><button class="btn ghost" data-go="${x.target}">Open</button></div>`).join("")}</section>
 <div class="grid two" style="margin-top:14px">${panel("ASK RUMBO",`<div class="form"><input id="aiPrompt" placeholder="Pregunta por roster, logbook, Fitness, Nutrition, finanzas o familia…"><button class="btn primary" id="askAi">Analizar</button></div><div id="aiAnswer" class="callout" style="margin-top:12px"><b>RUMBO LOCAL · SIN API</b><p>El asistente analiza tus datos guardados mediante reglas locales. No utiliza servicios de IA externos ni envía información fuera del dispositivo.</p></div>`)}
 ${panel("MONTHLY FLIGHT SNAPSHOT",`<div class="row"><b>${monthKey}</b><strong>${flightTime(monthHours)} flying hours</strong></div><div class="row"><span>Rostered days</span><b>${month.days}</b></div><div class="row"><span>Flight duty days (roster)</span><b>${month.FLIGHT}</b></div><div class="row"><span>OFF / standby</span><b>${month.OFF} / ${month.STANDBY}</b></div><div class="row"><span>Logbook sectors</span><b>${monthSectors.length}</b></div>`)}
 ${panel("AUTONOMY & APPROVALS",`<div class="row"><b>Analysis and draft suggestions</b><span class="pill">Allowed</span></div><div class="row"><b>Calendar / roster changes</b><span class="pill">Approval required</span></div><div class="row"><b>Purchases and payments</b><span class="pill">Never autonomous</span></div><div class="row"><b>Operational flight decisions</b><span class="pill">Out of scope</span></div><p class="muted">No se emitirán instrucciones operacionales ni se sustituirán los manuales, SOP o decisiones del operador. El modelo responde solo a la información incluida en cada consulta; no ejecuta cambios ni decisiones operacionales.</p>`)}
 ${panel("AI ACTIVITY LOG",logs.length?logs.slice().reverse().map(x=>`<div class="row"><span><b>${esc(x.question)}</b><small>${esc(x.answer)}</small></span><small>${dateText(x.date)}</small></div>`).join(""):`<div class="empty">Aquí quedará constancia de las consultas y propuestas generadas.</div>`)}
 </div>`;
}
