function formatClock(ms){const n=Math.floor(ms/1000),h=Math.floor(n/3600),m=Math.floor(n%3600/60),sec=n%60;return [h,m,sec].map(x=>String(x).padStart(2,"0")).join(":")}
function syncWorkoutClocks(){const t=state.workoutTimer||{},elapsed=workoutElapsed();["#workoutClock","#activeWorkoutClock"].forEach(sel=>{const el=$(sel);if(el)el.textContent=formatClock(elapsed)});["#workoutClockStatus","#activeWorkoutClockStatus"].forEach(sel=>{const el=$(sel);if(el)el.textContent=t.running?"IN PROGRESS":elapsed?"PAUSED":"READY"});if(t.running&&!workoutClockInterval)workoutClockInterval=setInterval(()=>{["#workoutClock","#activeWorkoutClock"].forEach(sel=>{const e=$(sel);if(e)e.textContent=formatClock(workoutElapsed())})},1000);if(!t.running&&workoutClockInterval){clearInterval(workoutClockInterval);workoutClockInterval=null}const rest=state.restTimer||{},remaining=Math.max(0,(Number(rest.endsAt)||0)-Date.now());["#restClock","#activeRestClock"].forEach(sel=>{const el=$(sel);if(el)el.textContent=formatClock(remaining)});if(rest.running&&!restClockInterval)restClockInterval=setInterval(()=>{const left=Math.max(0,(Number(state.restTimer?.endsAt)||0)-Date.now());["#restClock","#activeRestClock"].forEach(sel=>{const el=$(sel);if(el)el.textContent=formatClock(left)});if(left<=0){clearInterval(restClockInterval);restClockInterval=null;state.restTimer={running:false,endsAt:0};save();toast("Rest interval complete.")}},250);if(!rest.running&&restClockInterval){clearInterval(restClockInterval);restClockInterval=null}}

