window.rumboCloudSync=initRumboCloudSync({
 getLocalState:()=>state,
 hasLocalContent:()=>["duties","reminders","events","workouts","shopping","expenses","incomes","debts","assets","sleepLogs","dailyCheckins","hydrationLogs","habitLogs","logbook","recommendations","mealPlan","pantry","customRecipes","recipeSearchResults","receiptDraftItems","trainingPlan","trainingGoals","aviationTraining","aiLog","rosterHotels","rosterTraining","airportNotes","crewBids","crewBidHistory","healthDaily","foodDiary","exerciseProgress","fitnessHistory","fitnessWeightLogs"].some(key=>Array.isArray(state[key])&&state[key].length>0)||Object.keys(state.budgets||{}).length>0||["fitnessProfile","nutritionProfile","fitnessJourney","waderImportSummary"].some(key=>state[key]&&typeof state[key]==="object"&&Object.keys(state[key]).length>0)||Array.isArray(state.trainingProgram?.sessions)&&state.trainingProgram.sessions.length>0||Number(state.previousExperienceHours)>0||JSON.stringify(state.crewBiddingProfile)!==JSON.stringify(DEFAULT_CREW_BIDDING_PROFILE),
 onRemoteState:(remote)=>{
  try{state=normalizeState(remote);localStorage.setItem(KEY,JSON.stringify(state));render();toast("RUMBO actualizado desde otro dispositivo.")}catch(error){console.error("Remote RUMBO state rejected",error);toast("No se pudo aplicar la sincronización remota.")}
 }
});
if('serviceWorker' in navigator && location.protocol.startsWith('http')) navigator.serviceWorker.register('./sw.js').catch(()=>{});

